update lessons set objective_ar='أحلّل قصة «عاشق الجدار القديم» للكاتب الإماراتي علي عبد العزيز الشرهان إلى عناصرها، وأفسّر رمز الجدار ووظائف الوصف، وأستنتج قيم الهوية والتضحية، وأوازن بينها وبين قصص المجموعة القصصية «كلنا كلنا نحب البحر».' where code='AR-Y8-N-T3-L03';
update success_criteria set statement_ar='أحدّد الراوي والشخصيات والإطار.' where sort_order=1 and lesson_id=(select id from lessons where code='AR-Y8-N-T3-L03');
update success_criteria set statement_ar='أفسّر رمز الجدار وأحلّل وظائف الوصف.' where sort_order=2 and lesson_id=(select id from lessons where code='AR-Y8-N-T3-L03');
update success_criteria set statement_ar='أقارن القصة بـ«أحلام طفلة» في تعبيرهما عن البحر والذاكرة.' where sort_order=3 and lesson_id=(select id from lessons where code='AR-Y8-N-T3-L03');
update lesson_summaries set content=content||'{"hook": "جدار قديم على الشاطئ… ماذا يحفظ من ليلة الخوف والصمود؟", "idea": "قصة من المجموعة القصصية يصمد فيها رجال الساحل أمام عدوّ يقصفهم من البحر، ويخاطر الراوي بحياته، ويبقى الجدار القديم شاهدًا يحمل ذاكرة التضحية.", "learn": [["📖", "أقرأ القصة في كتابي ص 41–46."], ["🌊", "رجال يتمترسون خلف أكياس الرمل على الشاطئ."], ["🔥", "عدوّ رابض في البحر يحرق البيوت."], ["🧱", "الجدار آخر الأطلال: رمز ذاكرة التضحية."], ["💡", "أطبّق المهارة وأربطها بحياتي."]], "quiz": [["الجدار في القصة رمز لذاكرة المكان والتضحية.", true], ["القصة تدور حول بناء جدار جديد.", false]]}'::jsonb where lesson_id=(select id from lessons where code='AR-Y8-N-T3-L03');